package io.raftline.core.chaos;

import java.time.Instant;
import java.util.List;
import java.util.Set;

/**
 * Diagnostic validation report generated by automated self-healing and invariant probes.
 */
public record ChaosValidationReport(
        Instant timestamp,
        String status,          // HEALTHY, DEGRADED, SPLIT_BRAIN_PROTECTED, CRITICAL
        String leaderId,
        long term,
        boolean leaderLeaseActive,
        long probeLatencyMs,
        int activeFaultCount,
        Set<String> isolatedPeers,
        List<String> checks,
        String summary
) {}
